function transformRuleOutput(ruleResults, enriched) {
  var DEDUPE = true
  var SKIP_ERRORED_RULES = false

  function isBlank(v) {
    return v === undefined || v === null || v === ""
  }

  function toArray(v) {
    if (Array.isArray(v)) return v
    return isBlank(v) ? [] : [v]
  }

  function pick(row) {
    if (!row || typeof row !== "object") return undefined
    var aliases = Array.prototype.slice.call(arguments, 1)
    var keys = Object.keys(row)
    for (var a = 0; a < aliases.length; a++) {
      var want = String(aliases[a]).toLowerCase()
      for (var k = 0; k < keys.length; k++) {
        if (keys[k].toLowerCase() === want && !isBlank(row[keys[k]]))
          return row[keys[k]]
      }
    }
    return undefined
  }

  function groupFor(groups, key) {
    for (var i = 0; i < groups.length; i++) {
      if (groups[i].entitytype === key) return groups[i]
    }
    var created = { entitytype: key, requirements: [] }
    groups.push(created)
    return created
  }

  function extraFor(reqId, formIdNew) {
    if (!enriched) return {}
    var byReq = enriched[reqId]
    if (byReq) return byReq
    var byForm = enriched[formIdNew]
    return byForm ? byForm : {}
  }

  // NewReqId[i] pairs with newformId[i]; shorter list contributes null
  function pairUp(reqIds, formIds) {
    var count = Math.max(reqIds.length, formIds.length)
    if (count === 0) return []
    var pairs = []
    for (var p = 0; p < count; p++) {
      pairs.push({
        reqId: p < reqIds.length ? reqIds[p] : null,
        formIdNew: p < formIds.length ? formIds[p] : null,
      })
    }
    return pairs
  }

  var groups = []
  var results = toArray(ruleResults)

  for (var i = 0; i < results.length; i++) {
    var result = results[i] || {}
    if (SKIP_ERRORED_RULES && !isBlank(result.errors)) continue

    var rows = toArray(result.output)

    for (var r = 0; r < rows.length; r++) {
      var row = rows[r] || {}
      if (row.defaultOutputData !== true) continue

      var reqIds = toArray(pick(row, "NewReqId", "reqId", "requirementId"))
      var formIds = toArray(
        pick(row, "NewFormId", "newformId", "formIdNew", "formId")
      )
      var entityTypes = toArray(
        pick(row, "entityType", "entity_type", "entitytype")
      )
      if (!entityTypes.length && !reqIds.length) continue
      if (!entityTypes.length) entityTypes = ["UNKNOWN"]

      var pairs = pairUp(reqIds, formIds)
      if (!pairs.length) pairs = [{ reqId: null, formIdNew: null }]

      var docIds = toArray(pick(row, "DocId", "docId", "docID", "documentId"))

      var ruleDescription = pick(
        row,
        "ruleDescription",
        "ruledesc",
        "description"
      )
      if (isBlank(ruleDescription)) ruleDescription = ""

      var status = pick(
        row,
        "RequirementStatus",
        "requirementStatus",
        "reqstatus"
      )
      var ruleId = pick(row, "ruleId")

      for (var e = 0; e < entityTypes.length; e++) {
        var group = groupFor(groups, String(entityTypes[e]))

        for (var p = 0; p < pairs.length; p++) {
          var reqId = pairs[p].reqId
          var formIdNew = pairs[p].formIdNew
          var extra = extraFor(reqId, formIdNew)
          var target = null

          if (DEDUPE) {
            for (var q = 0; q < group.requirements.length; q++) {
              if (
                group.requirements[q].reqId === reqId &&
                group.requirements[q].formIdNew === formIdNew
              ) {
                target = group.requirements[q]
                break
              }
            }
          }

          if (target) {
            for (var n = 0; n < docIds.length; n++) {
              var seen = false
              for (var s = 0; s < target.documents.length; s++) {
                if (target.documents[s].documentId === docIds[n]) {
                  seen = true
                  break
                }
              }
              if (!seen) target.documents.push({ documentId: docIds[n] })
            }
            if (isBlank(target.ruleDescription))
              target.ruleDescription = ruleDescription
            if (isBlank(target.requirementStatus))
              target.requirementStatus = isBlank(status) ? null : status
            continue
          }

          var copies = []
          for (var c = 0; c < docIds.length; c++)
            copies.push({ documentId: docIds[c] })

          group.requirements.push({
            bmi: isBlank(extra.bmi) ? "" : extra.bmi,
            formIdNew: formIdNew,
            reqId: reqId,
            requirementCategory: isBlank(extra.requirementCategory)
              ? ""
              : extra.requirementCategory,
            requirementStatus: isBlank(status) ? null : status,
            ruleId: isBlank(ruleId) ? null : ruleId,
            ruleDescription: ruleDescription,
            documents: copies,
          })
        }
      }
    }
  }

  return groups
}

