function transform(input) {
  return input.map((item) => {
    const { entity_type, loop_response = [] } = item.output;

    return {
      entityType: entity_type,
      requirements: loop_response.map((loop) => {
        const ref = loop.output.object_reference || {};
        const req = (loop.output.requirements || [])[0] || {};
        const docs = loop.output.documents || [];

        return {
          bmi: ref.bmi || "",
          formIdOld: req.Old_Form_ID || "",
          formIdNew: ref.formIdNew || "",
          reqCodeOld: req.OLD_REQ_CD || "",
          reqCodeNew: ref.reqId || "",
          reqName: (req.REQ_LABEL_NAME || "").trim(),
          requirementCategory: req.REQ_CAT || "",
          requirementStatus: ref.requirementStatus || "",
          minDocRequired: "",
          isReqVisibile: req.IS_UI_VISIBLE === "Y",
          isDocumentUploadAllowed: req.IS_UPLOAD_ALLOWED === "Y",
          ruleId: ref.ruleId || "",
          ruleDescription: "",
          documents: docs.map((d) => ({
            documentId: d.DOC_ID,
            documentName: d.DOC_LABEL_NAME,
            isMandatory: true
          }))
        };
      })
    };
  });
}
